import{_ as r,r as i,o as c,c as d,e as n,a as e,s as a,d as t}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Multisite - October CMS - 4.x","titleTemplate":false,"description":"Learn how to translate content using multiple sites","frontmatter":{"subtitle":"Learn how to translate content using multiple sites"},"headers":[{"level":2,"title":"Managing Sites","slug":"managing-sites","link":"#managing-sites","children":[]},{"level":2,"title":"Site Routing","slug":"site-routing","link":"#site-routing","children":[{"level":3,"title":"How Requests Are Matched","slug":"how-requests-are-matched","link":"#how-requests-are-matched","children":[]},{"level":3,"title":"Default Site Fallback","slug":"default-site-fallback","link":"#default-site-fallback","children":[]},{"level":3,"title":"Best Practices","slug":"best-practices","link":"#best-practices","children":[]}]},{"level":2,"title":"Site Picker Component","slug":"site-picker-component","link":"#site-picker-component","children":[]},{"level":2,"title":"Browser Language Detection","slug":"browser-language-detection","link":"#browser-language-detection","children":[]},{"level":2,"title":"Site Groups","slug":"site-groups","link":"#site-groups","children":[]},{"level":2,"title":"Role Restrictions","slug":"role-restrictions","link":"#role-restrictions","children":[]},{"level":2,"title":"Multisite Features","slug":"multisite-features","link":"#multisite-features","children":[{"level":3,"title":"Per-Site Plugin Management","slug":"per-site-plugin-management","link":"#per-site-plugin-management","children":[]},{"level":3,"title":"Disabling Multisite","slug":"disabling-multisite","link":"#disabling-multisite","children":[]}]},{"level":2,"title":"PHP Interface","slug":"php-interface","link":"#php-interface","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/cms/multisite/multisite.md","filePath":"4.x/cms/multisite/multisite.md"}'),h={name:"4.x/cms/multisite/multisite.md"};function p(u,s,g,m,f,b){const o=i("pre-heading"),l=i("post-heading");return c(),d("div",null,[n(o),s[0]||(s[0]=e("h1",null,"Multisite",-1)),n(l),s[1]||(s[1]=a(`<p>The multisite feature lets you manage multiple websites from a single October CMS installation and assign content dependent on the domain name. For example, an e-commerce store with different country-specific sub-sites. You can also use it to manage translations for a localized website.</p><h2 id="managing-sites"><a href="#managing-sites" class="header-anchor">#</a> Managing Sites</h2><p>You can create sites by visiting the admin panel&#39;s <strong>Settings → Manage Sites</strong> page. Every installation includes a primary site that acts as the default site for every request.</p><p>The following configuration defines each site:</p><ul><li><strong>Enabled</strong> - determines if you can access the site on the front end and admin panel.</li><li><strong>Name</strong> - specifies the site name.</li><li><strong>Unique Code</strong> - specifies a unique site code for lookup using APIs.</li><li><strong>Theme</strong> - the CMS theme to use when this site is active.</li><li><strong>Locale</strong> - the application locale used for this site.</li><li><strong>Timezone</strong> - the timezone to use for this site.</li><li><strong>Custom application URL</strong> - the URL to use when this site is active, for things like mail templates or when the link policy forces the URL.</li><li><strong>Use a CMS route prefix</strong> - defines a prefix to include before every page route. It can identify this site when using a shared hostname.</li><li><strong>Define matching hostnames</strong> - matches the site using specific hostnames. You should enable this for production sites for security reasons. Wildcard values are supported, e.g.: <code>*.mydomain.tld</code>.</li><li><strong>Display a color for this site</strong> - when enabled, displays a banner at the top of the admin panel. Useful to identify the active site or distinguish different environments, for example, red for development, green for staging and no color for production.</li></ul><p>When you create more than one site, each can be selected in the admin panel using the site selection dropdown menu.</p><h2 id="site-routing"><a href="#site-routing" class="header-anchor">#</a> Site Routing</h2><p>When a request arrives, October CMS determines which site should handle it by matching the request against each site definition. Understanding this process is important when running multiple sites on different domains.</p><h3 id="how-requests-are-matched"><a href="#how-requests-are-matched" class="header-anchor">#</a> How Requests Are Matched</h3><p>The system uses a two-stage matching process to resolve the active site for each request.</p><ol><li><p><strong>Hostname matching</strong>: if a site has <strong>Define matching hostnames</strong> enabled, it will only match requests for those specific hostnames. If a site does not have this option enabled, it will match requests from <strong>any hostname</strong>.</p></li><li><p><strong>Route prefix matching</strong>: if a site has <strong>Use a CMS route prefix</strong> enabled, the request URI must match the prefix. For example, a site with the prefix <code>/en</code> will match <code>/en</code> and <code>/en/about</code> but not <code>/fr/about</code>.</p></li></ol><p>When multiple sites match, the site with the most specific route prefix takes priority. If no site matches the request, the primary site is used as the fallback.</p><h3 id="default-site-fallback"><a href="#default-site-fallback" class="header-anchor">#</a> Default Site Fallback</h3><p>The primary site acts as a catch-all when no other site matches. However, if the primary site does not have its hostnames restricted, it will match <strong>every request</strong>, including requests intended for other domains.</p><p>For example, consider the following configuration.</p><div class="table"><table tabindex="0"><thead><tr><th>Site</th><th>Hostname Restriction</th><th>Theme</th></tr></thead><tbody><tr><td>Primary Site</td><td><em>None</em></td><td>default-theme</td></tr><tr><td>Secondary Site</td><td><code>www.domain2.tld</code></td><td>other-theme</td></tr></tbody></table></div><p>In this case, a request to <code>www.domain2.tld</code> will match <strong>both</strong> sites — the Secondary Site matches by hostname, and the Primary Site matches because it has no hostname restriction. This can result in the wrong theme being displayed.</p><h3 id="best-practices"><a href="#best-practices" class="header-anchor">#</a> Best Practices</h3><p>To avoid unexpected routing, you should restrict the hostnames of every site, including the primary site. The following configuration ensures each site only responds to its intended domain.</p><div class="table"><table tabindex="0"><thead><tr><th>Site</th><th>Hostname Restriction</th><th>Theme</th></tr></thead><tbody><tr><td>Primary Site</td><td><code>cms.domain.tld</code></td><td>default-theme</td></tr><tr><td>Secondary Site</td><td><code>www.domain2.tld</code></td><td>other-theme</td></tr></tbody></table></div><p>Alternatively, if the primary site is only used for managing content in the admin panel, you can disable it on the frontend by unchecking <strong>Enabled</strong> while keeping it accessible in the backend.</p><div class="custom-block tip"><p>Always enable <strong>Define matching hostnames</strong> for production sites. This prevents one site from unintentionally serving content for another domain.</p></div><h2 id="site-picker-component"><a href="#site-picker-component" class="header-anchor">#</a> Site Picker Component</h2><p>The <code>sitePicker</code> component lets you manage links to other sites. The best place to include this is in your page or layout template.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">sitePicker</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> availableSites <span class="token operator">=</span> sitePicker<span class="token punctuation">.</span>sites <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>View the <a href="./../components/sitepicker.html">Site Picker component</a> article to learn how to display site URLs and generating alternative page links.</p><h2 id="browser-language-detection"><a href="#browser-language-detection" class="header-anchor">#</a> Browser Language Detection</h2><p>October CMS is configured to automatically detect a matching site based on the browser&#39;s preferred language when the following conditions are met.</p><ul><li>All sites in the group have a prefix set</li><li>There are no other sites matching the base URL</li></ul><p>For example, if the primary site is <strong>English</strong> with a route prefix of <code>/en</code> and another site <strong>French</strong> has a prefix of <code>/fr</code> then the following behavior can be observed.</p>`,30)),s[2]||(s[2]=e("div",{class:"table"},[e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",null,"Base URL"),e("th",null,"Behavior")])]),e("tbody",null,[e("tr",null,[e("td",null,[e("a",{href:"https://yoursite.tld/en",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[t("https://yoursite.tld/en"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),t(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),t(),e("span",{class:"sr-only"},"(opens new window)")])])]),e("td",null,[t("Displays the "),e("strong",null,"English"),t(" site")])]),e("tr",null,[e("td",null,[e("a",{href:"https://yoursite.tld/fr",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[t("https://yoursite.tld/fr"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),t(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),t(),e("span",{class:"sr-only"},"(opens new window)")])])]),e("td",null,[t("Displays the "),e("strong",null,"French"),t(" site")])]),e("tr",null,[e("td",null,[e("a",{href:"https://yoursite.tld",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[t("https://yoursite.tld"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),t(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),t(),e("span",{class:"sr-only"},"(opens new window)")])])]),e("td",null,"Redirect based on language preference")])])])],-1)),s[3]||(s[3]=a(`<p>When the user visits the base URL, their preferred language is automatically detected and will be redirected to a matching site. The matching site is based on its locale value and if no match is found then the primary site is used.</p><div class="custom-block tip"><p>You can modify this behavior using the <code>redirect_policy</code> value found in the <strong>config/cms.php</strong> file.</p></div><h2 id="site-groups"><a href="#site-groups" class="header-anchor">#</a> Site Groups</h2><p>In its initial state, multisite is helpful in creating multiple websites in a single language, or a single website using multiple languages. Grouping sites allow you to extend this concept further to create multiple sites with multiple languages. Create site groups by navigating to <strong>Settings → Manage Sites → Manage Site Groups</strong>, and once a group is created, a group selection field should appear for each site.</p><p>In practical terms, each site group represents a website and site definitions belonging to the group represent the site in an alternative language. The following example shows a grouped site configuration for a website about cats and dogs with two languages for each.</p><div class="table"><table tabindex="0"><thead><tr><th>Site Group</th><th>Site Name</th></tr></thead><tbody><tr><td>Dogs</td><td>English</td></tr><tr><td>Dogs</td><td>French</td></tr><tr><td>Cats</td><td>English</td></tr><tr><td>Cats</td><td>French</td></tr></tbody></table></div><p>Grouped sites will only replicate fields within their specific group. For example, if a <a href="./../tailor/introduction.html">Tailor blueprint</a> uses the <code>multisite: sync</code> option, the records will only synchronize across sites in the same group.</p><h2 id="role-restrictions"><a href="#role-restrictions" class="header-anchor">#</a> Role Restrictions</h2><p>Site definitions can restrict their visibility based on the administrator role, which allows you to use dedicated administrator roles to manage a specific sites. To enable the multisite role restrictions feature:</p><ol><li>Navigate to <strong>Manage Sites</strong> and select a site definition</li><li>Place check in the <strong>Define administrator roles</strong> checkbox.</li><li>Select the roles allowed to view the site.</li><li>Click <strong>Save</strong>.</li></ol><p>When enabled, the site will only be visible in the backend panel to administrators that are specified in the field. For example, to create a site that is only accessible to Developers, select the <strong>Developer</strong> role in the field.</p><h2 id="multisite-features"><a href="#multisite-features" class="header-anchor">#</a> Multisite Features</h2><p>There are some core features that are not multisite-enabled by default, such as the mail configuration. You may selectively enable multisite features using the <strong>config/multisite.php</strong> file found under the <code>features</code> section. The following feature keys are available to use with multiple site definitions.</p><div class="table"><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><code>system_plugin_sites</code></td><td>Plugins can be enabled or disabled per site</td></tr><tr><td><code>system_plugin_site_groups</code></td><td>Plugins can be enabled or disabled per site group</td></tr><tr><td><code>system_asset_combiner</code></td><td>Asset combiner cache keys are unique to the site</td></tr><tr><td><code>cms_maintenance_setting</code></td><td>Maintenance Mode Settings are unique for each site</td></tr><tr><td><code>backend_mail_setting</code></td><td>Mail Settings are unique for each site</td></tr><tr><td><code>backend_mail_template</code></td><td>Mail templates translate via attributes and locale view directories</td></tr><tr><td><code>dashboard_traffic_statistics</code></td><td>Dashboard traffic statistics are unique for each site</td></tr></tbody></table></div><h3 id="per-site-plugin-management"><a href="#per-site-plugin-management" class="header-anchor">#</a> Per-Site Plugin Management</h3><p>When the <code>system_plugin_sites</code> or <code>system_plugin_site_groups</code> feature is enabled, you can enable or disable plugins for individual sites or site groups. Navigate to <strong>Settings → Updates &amp; Plugins → Manage Plugins</strong> and use the toggle switch next to each plugin to control its availability for the currently selected site.</p><p>A plugin that is disabled for a site will have its backend navigation, settings and controllers hidden for that site. Switching to a different site using the site picker will restore access to the plugin if it is enabled there.</p><div class="custom-block tip"><p>You must clear the application cache after enabling or disabling these features in the configuration file.</p></div><h3 id="disabling-multisite"><a href="#disabling-multisite" class="header-anchor">#</a> Disabling Multisite</h3><p>You may disable the multisite features entirely by setting the <code>enabled</code> configuration to a <code>false</code> value.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;enabled&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span>
</code></pre></div><h2 id="php-interface"><a href="#php-interface" class="header-anchor">#</a> PHP Interface</h2><p>The <a href="./../../extend/services/site.html">site service</a> includes the global <code>Site</code> facade that provides tools for working with multisite. For example, the following code locates a model in the context of the site with ID <strong>2</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">withContext</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Model</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Read the <a href="./../../extend/services/site.html">Site Service article</a> to learn more.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4>`,26)),s[4]||(s[4]=e("div",{class:"custom-block also"},[e("ul",null,[e("li",null,[e("a",{href:"https://octobercms.com/features/multisite",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[t("Multisite Features"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),t(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),t(),e("span",{class:"sr-only"},"(opens new window)")])])]),e("li",null,[e("a",{href:"./localization.html"},"Theme Localization")]),e("li",null,[e("a",{href:"./tailor.html"},"Tailor Localization")]),e("li",null,[e("a",{href:"./../components/sitepicker.html"},"Site Picker Component")]),e("li",null,[e("a",{href:"./../../extend/multisite/multisite.html"},"Multisite Trait")]),e("li",null,[e("a",{href:"./../../extend/services/site.html"},"Site Service")])])],-1))])}const y=r(h,[["render",p]]);export{w as __pageData,y as default};
